 function activityReportBody(r){const groups={};r.events.forEach(a=>{const label=eventLabel({...a,after_data:{state:a.state}});groups[label]=(groups[label]||0)+1;});return `<h2>${E(r.profile.name)}</h2><p>${E(M.dept(r.profile.department))} · ${E(r.from)} — ${E(r.to)}</p><p class="cm-muted">${E(r.scope)}</p><h3>ملخص النشاط الفعلي</h3>`+table(['الإجراء','العدد'],Object.entries(groups).map(([k,n])=>tr([E(k),n])))+'<h3>المقررات المكلف بها حاليًا (ليست إعادة بناء لتكليفات الماضي)</h3>'+table(['المقرر','الترم','التكليف الحالي'],r.current_assignments.map(o=>tr([E(o.course+' — '+o.code),E(o.term),E([o.coordinator?'منسق':'',o.schedule_lecturer?'محاضر من الجدول':'',...(o.current_grants||[]).flatMap(g=>Object.keys(g).filter(k=>g[k]).map(k=>permissionLabels[k]))].filter(Boolean).join('، '))])))+'<h3>الإجراءات والتحديثات والتسليمات والمراجعات</h3>'+table(['التاريخ','المقرر / الترم','الإجراء','الملاحظة'],r.events.map(a=>tr([E(M.stamp(a.created_at)),E(a.course)+'<br>'+E(a.term),E(eventLabel({...a,after_data:{state:a.state}})),E(a.comment)])))+'<h3>رصد التأخر الموثق وقت الإجراء</h3>'+table(['المقرر / التاريخ','نوع التأخر','البيان'],r.timings.map(x=>tr([E(x.course)+'<br>'+E(M.stamp(x.created_at)),x.timing.kind==='submission'?'تسليم':'انتظار مراجعة',x.timing.kind==='submission'?E('بنود متأخرة داخل التكليف الموثق: '+(x.timing.attributable_items||[]).length+'؛ رُصد إجمالًا: '+(x.timing.observed_items||[]).length+'؛ بداية التكليف المثبتة: '+(x.timing.assignment_since?M.stamp(x.timing.assignment_since):'غير موثقة — لا نسبة شخصية للتأخير')):E('انتظار المرحلة: '+(x.timing.review?.days_late||0)+' يوم؛ لا يُنسب تلقائيًا لهذا المراجع')])));}

